import java.security.*;import java.math.*;import java.util.*;
public class MD5{public static void main(String[]x)throws Exception{Scanner s=new Scanner(System.in);System.out.print("Enter text (record sample cryptography): ");String m=s.nextLine();byte[]d=MessageDigest.getInstance("MD5").digest(m.getBytes(java.nio.charset.StandardCharsets.UTF_8));String h=new BigInteger(1,d).toString(16);while(h.length()<32)h="0"+h;System.out.println("Your HashCode Generated by MD5 is: "+h);}}
